import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Compress values so window frequencies live in an array.
        long[] vals = a.clone();
        Arrays.sort(vals);
        int size = 0;
        for (int i = 0; i < n; i++) if (i == 0 || vals[i] != vals[i - 1]) vals[size++] = vals[i];
        int[] id = new int[n], freq = new int[size];
        for (int i = 0; i < n; i++) id[i] = Arrays.binarySearch(vals, 0, size, a[i]);
        long answer = 0;
        int left = 0, distinct = 0;
        for (int right = 0; right < n; right++) {
            if (freq[id[right]]++ == 0) distinct++;
            while (distinct > k)
                if (--freq[id[left++]] == 0) distinct--;
            answer += right - left + 1;  // every start in [left, right] is stable
        }
        System.out.println(answer % 1000000007L);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Compress values so window frequencies live in an array.
	vals := slices.Clone(a)
	slices.Sort(vals)
	vals = slices.Compact(vals)
	id := make([]int, n)
	for i, v := range a {
		id[i], _ = slices.BinarySearch(vals, v)
	}
	freq := make([]int, len(vals))
	var answer int64
	left, distinct := 0, 0
	for right := 0; right < n; right++ {
		if freq[id[right]] == 0 {
			distinct++
		}
		freq[id[right]]++
		for distinct > k {
			freq[id[left]]--
			if freq[id[left]] == 0 {
				distinct--
			}
			left++
		}
		answer += int64(right - left + 1) // every start in [left, right] is stable
	}
	fmt.Println(answer % 1000000007)
}
